contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(uint _am) public payable {
        // Read the observable state before the call.
        uint oldBal = c.Acc(address(this)).balance;
        uint cEthBefore = address(c).balance;
        uint myEthBefore = address(this).balance;

        // The deciding call.
        c.Collect(_am);

        // Read the observable state after the call.
        uint newBal = c.Acc(address(this)).balance;
        uint cEthAfter = address(c).balance;
        uint myEthAfter = address(this).balance;

        // General rule: Collect can never increase the stored balance, and if it
        // changes the stored balance at all, it must be by exactly _am, with
        // exactly _am Ether moved from c to the caller.
        assert(
            newBal <= oldBal
            && (
                newBal == oldBal
                || (
                    newBal + _am == oldBal
                    && myEthAfter == myEthBefore + _am
                    && cEthAfter <= cEthBefore
                    && cEthBefore - cEthAfter == _am
                )
            )
        );
    }

    receive() external payable {}
}

